/* Framer scroll-appear animations — translateY kept small to avoid breaking IntersectionObserver */
[data-framer-appear-id] { opacity: 0; transform: translateY(24px); transition: opacity 0.6s cubic-bezier(0.22,1,0.36,1), transform 0.6s cubic-bezier(0.22,1,0.36,1); will-change: opacity, transform; }
[data-framer-appear-id].appeared { opacity: 1 !important; transform: none !important; }

/* Framer vertical ticker/marquee — infinite scroll upward */
@keyframes framerTickerScroll {
  from { transform: translateY(0); }
  to   { transform: translateY(-50%); }
}
[data-framer-ticker="vertical"] {
  height: auto !important;
  max-height: none !important;
  animation: framerTickerScroll 20s linear infinite;
  list-style: none;
  margin: 0;
  padding: 0;
}
[data-framer-ticker="vertical"]:hover { animation-play-state: paused; }

/* Framer horizontal ticker/marquee — infinite scroll leftward */
@keyframes framerTickerScrollH {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}
[data-framer-ticker="horizontal"] {
  width: max-content !important;
  max-width: none !important;
  flex-wrap: nowrap !important;
  animation: framerTickerScrollH 20s linear infinite;
  list-style: none;
  margin: 0;
  padding: 0;
}
[data-framer-ticker="horizontal"]:hover { animation-play-state: paused; }

